import java.util.*;

class Solution {
    int[] ans;
    List<Integer>[] adj;
    int[] nums;
    boolean[][] coprime;
    int[] lastNode = new int[51];
    int[] lastDepth = new int[51];

    public int[] getCoprimes(int[] nums, int[][] edges) {
        int n = nums.length;
        this.nums = nums;
        ans = new int[n];
        adj = new List[n];
        for (int i = 0; i < n; i++) adj[i] = new ArrayList<>();
        for (int[] e : edges) {
            adj[e[0]].add(e[1]);
            adj[e[1]].add(e[0]);
        }
        coprime = new boolean[51][51];
        for (int i = 1; i <= 50; i++)
            for (int j = 1; j <= 50; j++)
                coprime[i][j] = gcd(i, j) == 1;

        Arrays.fill(lastNode, -1);
        Arrays.fill(lastDepth, -1);

        // iterative DFS
        int[] stack = new int[n];
        int[] parent = new int[n];
        int[] depthArr = new int[n];
        // store saved state for restore
        int[] savedNode = new int[n];
        int[] savedDepth = new int[n];
        // We do explicit DFS with enter/exit
        // Use a stack of frames
        Deque<int[]> dq = new ArrayDeque<>();
        // frame: {node, parent, depth, state}
        dq.push(new int[]{0, -1, 0, 0});
        while (!dq.isEmpty()) {
            int[] fr = dq.peek();
            int node = fr[0], par = fr[1], depth = fr[2], state = fr[3];
            if (state == 0) {
                // enter
                int val = nums[node];
                int best = -1, bestDepth = -1;
                for (int v = 1; v <= 50; v++) {
                    if (lastNode[v] != -1 && coprime[val][v]) {
                        if (lastDepth[v] > bestDepth) {
                            bestDepth = lastDepth[v];
                            best = lastNode[v];
                        }
                    }
                }
                ans[node] = best;
                // save and set
                fr[3] = 1;
                fr[4] = lastNode[val];
                fr[5] = lastDepth[val];
                lastNode[val] = node;
                lastDepth[val] = depth;
                for (int nb : adj[node]) {
                    if (nb != par) {
                        dq.push(new int[]{nb, node, depth + 1, 0, 0, 0});
                    }
                }
            } else {
                // exit
                int val = nums[node];
                lastNode[val] = fr[4];
                lastDepth[val] = fr[5];
                dq.pop();
            }
        }
        return ans;
    }

    int gcd(int a, int b) {
        while (b != 0) { int t = a % b; a = b; b = t; }
        return a;
    }
}
