class Solution {
    boolean[] used = new boolean[10];
    int[] assigned = new int[26];
    boolean[] isAssigned = new boolean[26];
    boolean[] leading = new boolean[26];
    String[] words;
    String result;
    int maxLen;

    public boolean isSolvable(String[] words, String result) {
        this.words = words;
        this.result = result;
        maxLen = result.length();
        for (String w : words) {
            if (w.length() > maxLen) return false;
            maxLen = Math.max(maxLen, w.length());
        }
        for (int i = 0; i < 26; i++) { assigned[i] = -1; }
        for (String w : words) {
            if (w.length() > 1) leading[w.charAt(0)-'A'] = true;
        }
        if (result.length() > 1) leading[result.charAt(0)-'A'] = true;
        return solve(0, 0);
    }

    boolean solve(int col, int carry) {
        if (col == maxLen) {
            return carry == 0;
        }
        return processColumn(col, 0, carry, 0);
    }

    // idx: which word we're processing in this column (0..words.length for result)
    boolean processColumn(int col, int idx, int carry, int sum) {
        if (idx == words.length) {
            // now the result char
            int rIdx = result.length() - 1 - col;
            if (rIdx < 0) {
                // no result digit for this column, sum's last digit must be 0
                if (sum % 10 != 0) return false;
                return solve(col + 1, sum / 10);
            }
            char rc = result.charAt(rIdx);
            int ci = rc - 'A';
            int expectedDigit = sum % 10;
            int newCarry = sum / 10;
            if (isAssigned[ci]) {
                if (assigned[ci] != expectedDigit) return false;
                return solve(col + 1, newCarry);
            } else {
                if (used[expectedDigit]) return false;
                if (expectedDigit == 0 && leading[ci]) return false;
                assigned[ci] = expectedDigit;
                isAssigned[ci] = true;
                used[expectedDigit] = true;
                boolean res = solve(col + 1, newCarry);
                assigned[ci] = -1;
                isAssigned[ci] = false;
                used[expectedDigit] = false;
                return res;
            }
        }

        String w = words[idx];
        int wIdx = w.length() - 1 - col;
        if (wIdx < 0) {
            // this word has no digit in this column
            return processColumn(col, idx + 1, carry, sum);
        }
        char wc = w.charAt(wIdx);
        int ci = wc - 'A';
        if (isAssigned[ci]) {
            int add = (idx == 0) ? sum + carry + assigned[ci] : sum + assigned[ci];
            return processColumn(col, idx + 1, carry, add);
        } else {
            for (int d = 0; d < 10; d++) {
                if (used[d]) continue;
                if (d == 0 && leading[ci]) continue;
                used[d] = true;
                assigned[ci] = d;
                isAssigned[ci] = true;
                int add = (idx == 0) ? sum + carry + d : sum + d;
                if (processColumn(col, idx + 1, carry, add)) {
                    used[d] = false;
                    assigned[ci] = -1;
                    isAssigned[ci] = false;
                    return true;
                }
                used[d] = false;
                assigned[ci] = -1;
                isAssigned[ci] = false;
            }
            return false;
        }
    }
}
