    private List<String> makeNumbers(String s) {
        List<String> res = new ArrayList<>();
        int len = s.length();
        // no decimal point
        if (isValidInteger(s)) res.add(s);
        // with decimal point
        for (int i = 1; i < len; i++) {
            String intPart = s.substring(0, i);
            String fracPart = s.substring(i);
            if (isValidInteger(intPart) && isValidFraction(fracPart)) {
                res.add(intPart + "." + fracPart);
            }
        }
        return res;
    }

    private boolean isValidInteger(String s) {
        if (s.length() > 1 && s.charAt(0) == '0') return false;
        return true;
    }

    private boolean isValidFraction(String s) {
        if (s.charAt(s.length() - 1) == '0') return false;
        return true;
    }
