            int q = f(queries[i]);
            int lo = 0, hi = wf.length;
            while (lo < hi) {
                int mid = (lo + hi) / 2;
                if (wf[mid] > q) hi = mid;
                else lo = mid + 1;
            }
            ans[i] = wf.length - lo;
        }
