import java.util.*;

class Solution {
    public boolean canCross(int[] stones) {
        int n = stones.length;
        Map<Integer, Integer> index = new HashMap<>();
        for (int i = 0; i < n; i++) index.put(stones[i], i);
        Map<Integer, Set<Integer>> dp = new HashMap<>();
        for (int i = 0; i < n; i++) dp.put(i, new HashSet<>());
        dp.get(0).add(0);
        for (int i = 0; i < n; i++) {
            for (int k : dp.get(i)) {
                for (int step = k - 1; step <= k + 1; step++) {
                    if (step <= 0) continue;
                    int next = stones[i] + step;
                    if (index.containsKey(next)) {
                        int j = index.get(next);
                        if (j != i) dp.get(j).add(step);
                    }
                }
            }
        }
        return !dp.get(n - 1).isEmpty();
    }
}
