class Solution {
    public int maximumANDSum(int[] nums, int numSlots) {
        int[] pow = new int[numSlots + 1];
        pow[0] = 1;
        for (int i = 1; i <= numSlots; i++) pow[i] = pow[i-1] * 3;
        int total = pow[numSlots];
        int[] dp = new int[total];
        int best = 0;
        for (int mask = 0; mask < total; mask++) {
            int cnt = 0, tmp = mask;
            for (int i = 0; i < numSlots; i++) { cnt += tmp % 3; tmp /= 3; }
            if (cnt >= nums.length) { best = Math.max(best, dp[mask]); continue; }
            int idx = cnt;
            for (int s = 0; s < numSlots; s++) {
                int used = (mask / pow[s]) % 3;
                if (used < 2) {
                    int nmask = mask + pow[s];
                    int val = dp[mask] + (nums[idx] & (s + 1));
                    if (val > dp[nmask]) dp[nmask] = val;
                }
            }
        }
        return best;
    }
}
