class Solution {
    public int maxTotalFruits(int[][] fruits, int startPos, int k) {
        int n = fruits.length;
        int[] pos = new int[n];
        long[] prefix = new long[n + 1];
        for (int i = 0; i < n; i++) {
            pos[i] = fruits[i][0];
            prefix[i + 1] = prefix[i] + fruits[i][1];
        }
        long best = 0;
        int left = 0;
        for (int right = 0; right < n; right++) {
            while (left <= right) {
                int lp = pos[left], rp = pos[right];
                long cost;
                if (rp <= startPos) {
                    cost = startPos - lp;
                } else if (lp >= startPos) {
                    cost = rp - startPos;
                } else {
                    long leftDist = startPos - lp;
                    long rightDist = rp - startPos;
                    cost = Math.min(leftDist, rightDist) * 2 + Math.max(leftDist, rightDist);
                }
                if (cost <= k) break;
                left++;
            }
            if (left <= right) {
                best = Math.max(best, prefix[right + 1] - prefix[left]);
            }
        }
        return (int) best;
    }
}
