    public int maxStudents(char[][] seats) {
        int m = seats.length, n = seats[0].length;
        int[] valid = new int[m];
        for (int i = 0; i < m; i++) {
            int mask = 0;
            for (int j = 0; j < n; j++) {
                if (seats[i][j] == '.') mask |= (1 << j);
            }
            valid[i] = mask;
        }
        int full = 1 << n;
        int[] prev = new int[full];
        for (int i = 0; i < full; i++) prev[i] = -1;
        prev[0] = 0;
        for (int i = 0; i < m; i++) {
            int[] cur = new int[full];
            for (int j = 0; j < full; j++) cur[j] = -1;
            for (int state = 0; state < full; state++) {
                // valid seating
                if ((state & valid[i]) != state) continue;
                if ((state & (state << 1)) != 0) continue;
                for (int p = 0; p < full; p++) {
                    if (prev[p] < 0) continue;
                    if ((state & (p << 1)) != 0) continue;
                    if ((state & (p >> 1)) != 0) continue;
                    int cnt = prev[p] + Integer.bitCount(state);
