class Solution {
    public int minMalwareSpread(int[][] graph, int[] initial) {
        int n = graph.length;
        java.util.Arrays.sort(initial);
        boolean[] isInit = new boolean[n];
        for (int x : initial) isInit[x] = true;

        int best = -1, bestCount = Integer.MAX_VALUE;
        for (int remove : initial) {
            boolean[] infected = new boolean[n];
            java.util.ArrayDeque<Integer> queue = new java.util.ArrayDeque<>();
            for (int src : initial) {
                if (src == remove) continue;
                if (!infected[src]) {
                    infected[src] = true;
                    queue.add(src);
                }
            }
            while (!queue.isEmpty()) {
                int u = queue.poll();
                for (int v = 0; v < n; v++) {
                    if (v == remove) continue;
                    if (graph[u][v] == 1 && !infected[v]) {
                        infected[v] = true;
                        queue.add(v);
                    }
                }
            }
            int count = 0;
            for (int i = 0; i < n; i++) if (infected[i]) count++;
            if (count < bestCount) {
                bestCount = count;
                best = remove;
            }
        }
        return best;
    }
}
