class Solution {
    public int minCost(int maxTime, int[][] edges, int[] passingFees) {
        int n = passingFees.length;
        List<int[]>[] graph = new List[n];
        for (int i = 0; i < n; i++) graph[i] = new ArrayList<>();
        for (int[] e : edges) {
            graph[e[0]].add(new int[]{e[1], e[2]});
            graph[e[1]].add(new int[]{e[0], e[2]});
        }
        // dp[node][time] = min cost to reach node with exactly <= time
        int[][] cost = new int[n][maxTime + 1];
        for (int[] row : cost) Arrays.fill(row, Integer.MAX_VALUE);
        cost[0][0] = passingFees[0];
        // priority queue by cost
        PriorityQueue<int[]> pq = new PriorityQueue<>((a, b) -> a[0] - b[0]);
        pq.offer(new int[]{passingFees[0], 0, 0}); // cost, node, time
        int ans = Integer.MAX_VALUE;
        while (!pq.isEmpty()) {
            int[] cur = pq.poll();
            int c = cur[0], node = cur[1], t = cur[2];
            if (node == n - 1) return c;
            if (c > cost[node][t]) continue;
            for (int[] nb : graph[node]) {
                int nt = t + nb[1];
                if (nt > maxTime) continue;
                int nc = c + passingFees[nb[0]];
                if (nc < cost[nb[0]][nt]) {
                    cost[nb[0]][nt] = nc;
                    pq.offer(new int[]{nc, nb[0], nt});
                }
            }
        }
        return -1;
    }
}
