class Solution {
    public int minSessions(int[] tasks, int sessionTime) {
        int n = tasks.length;
        int full = 1 << n;
        // cost[mask] = 1 if tasks in mask fit in one session
        boolean[] fits = new boolean[full];
        for (int mask = 0; mask < full; mask++) {
            int sum = 0;
            for (int i = 0; i < n; i++) {
                if ((mask & (1 << i)) != 0) sum += tasks[i];
            }
            fits[mask] = sum <= sessionTime;
        }
        int[] dp = new int[full];
        java.util.Arrays.fill(dp, Integer.MAX_VALUE);
        dp[0] = 0;
        for (int mask = 1; mask < full; mask++) {
            // iterate submasks
            for (int sub = mask; sub > 0; sub = (sub - 1) & mask) {
                if (fits[sub] && dp[mask ^ sub] != Integer.MAX_VALUE) {
                    dp[mask] = Math.min(dp[mask], dp[mask ^ sub] + 1);
                }
            }
        }
        return dp[full - 1];
    }
}
