class Solution {
    static final int MOD = 1_000_000_007;
    long[][] C;

    public int numOfWays(int[] nums) {
        int n = nums.length;
        C = new long[n + 1][n + 1];
        for (int i = 0; i <= n; i++) {
            C[i][0] = 1;
            for (int j = 1; j <= i; j++) {
                C[i][j] = (C[i - 1][j - 1] + C[i - 1][j]) % MOD;
            }
        }
        java.util.List<Integer> list = new java.util.ArrayList<>();
        for (int x : nums) list.add(x);
        long ans = solve(list);
        ans = (ans - 1 + MOD) % MOD;
        return (int) ans;
    }

    long solve(java.util.List<Integer> arr) {
        int m = arr.size();
        if (m <= 2) return 1;
        int root = arr.get(0);
        java.util.List<Integer> left = new java.util.ArrayList<>();
        java.util.List<Integer> right = new java.util.ArrayList<>();
        for (int i = 1; i < m; i++) {
            if (arr.get(i) < root) left.add(arr.get(i));
            else right.add(arr.get(i));
        }
        long l = solve(left);
        long r = solve(right);
        long res = C[m - 1][left.size()];
        res = res * l % MOD;
        res = res * r % MOD;
        return res;
    }
}
