class Solution {
    public int maxSizeSlices(int[] slices) {
        int m = slices.length;
        int k = m / 3;
        int[] a = new int[m - 1];
        for (int i = 0; i < m - 1; i++) a[i] = slices[i];
        int r1 = solve(a, k);
        for (int i = 1; i < m; i++) a[i - 1] = slices[i];
        int r2 = solve(a, k);
        return Math.max(r1, r2);
    }

    private int solve(int[] a, int k) {
        int n = a.length;
        int[][] dp = new int[n + 1][k + 1];
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= k; j++) {
                int take = (i >= 2 ? dp[i - 2][j - 1] : 0) + a[i - 1];
                dp[i][j] = Math.max(dp[i - 1][j], take);
            }
        }
        return dp[n][k];
    }
}
