import java.util.TreeSet;
import java.util.Comparator;

class Solution {
    public double[] medianSlidingWindow(int[] nums, int k) {
        int n = nums.length;
        double[] res = new double[n - k + 1];
        // TreeSet of indices, ordered by value then index
        Comparator<Integer> cmp = (a, b) -> {
            if (nums[a] != nums[b]) return Integer.compare(nums[a], nums[b]);
            return Integer.compare(a, b);
        };
        TreeSet<Integer> lo = new TreeSet<>(cmp); // lower half (max at last)
        TreeSet<Integer> hi = new TreeSet<>(cmp); // upper half (min at first)

        for (int i = 0; i < n; i++) {
            // add i
            if (lo.isEmpty() || nums[i] <= nums[lo.last()]) {
                lo.add(i);
            } else {
                hi.add(i);
            }
            balance(lo, hi);

            // remove outgoing
            if (i >= k) {
                int out = i - k;
                if (lo.contains(out)) lo.remove(out);
                else hi.remove(out);
                balance(lo, hi);
            }

            if (i >= k - 1) {
                if (k % 2 == 1) {
                    res[i - k + 1] = (double) nums[lo.last()];
                } else {
                    res[i - k + 1] = ((double) nums[lo.last()] + (double) nums[hi.first()]) / 2.0;
                }
            }
        }
        return res;
    }

    private void balance(TreeSet<Integer> lo, TreeSet<Integer> hi) {
        // lo should have equal or one more than hi
        while (lo.size() > hi.size() + 1) {
            hi.add(lo.pollLast());
        }
        while (lo.size() < hi.size()) {
            lo.add(hi.pollFirst());
        }
    }
}
