class Solution {
    public int sumOddLengthSubarrays(int[] arr) {
        int n = arr.length;
        int total = 0;
        for (int i = 0; i < n; i++) {
            int left = i + 1;
            int right = n - i;
            int totalCount = left * right;
            int oddCount = (totalCount + 1) / 2;
            total += oddCount * arr[i];
        }
        return total;
    }
}
