Looking at this problem, I need to simulate rounds where positions matter.

Let me think in terms of positions. In each round with `k` players, position `i` (1-indexed) competes against position `k+1-i`. I track the positions of the two special players.

I'll write a recursive function that, given the number of players `n` and positions `f`, `s` of the two players, computes min and max round they meet.

If `f + s == n + 1`, they meet this round.

Otherwise, I enumerate all possible outcomes: for each pair, either left or right survives (except when it involves f or s, they must survive). Then compute their new positions among survivors and recurse.

Let me use memoization.

```java
import java.util.*;

class Solution {
    Map<String, int[]> memo = new HashMap<>();

    public int[] earliestAndLatest(int n, int firstPlayer, int secondPlayer) {
        return solve(n, firstPlayer, secondPlayer);
    }

    int[] solve(int n, int f, int s) {
        if (f > s) { int t = f; f = s; s = t; }
        // by symmetry: position f from front <-> mirror
        if (f - 1 > n - s) {
            int nf = n + 1 - s;
            int ns = n + 1 - f;
            f = nf; s = ns;
        }
        String key = n + "," + f + "," + s;
        if (memo.containsKey(key)) return memo.get(key);

        if (f + s == n + 1) {
            int[] res = new int[]{1, 1};
            memo.put(key, res);
            return res;
        }

        int minR = Integer.MAX_VALUE, maxR = Integer.MIN_VALUE;
        int half = n / 2;
        // enumerate outcomes of the pairs on the left half (positions 1..half)
        // for each pair (i, n+1-i), one survives
        // f and s must survive. Their new positions determined by how many below survive.
        // recurse over choices
        int[] r = enumerate(n, f, s, 1, new ArrayList<>());
        minR = r[0]; maxR = r[1];
        memo.put(key, r);
        return r;
    }

    // survivors: list of surviving original positions (from left perspective)
    int[] enumerate(int n, int f, int s, int i, List<Integer> survivors) {
        int half = n / 2;
        if (i > half) {
            // middle player advances if odd
            List<Integer> all = new ArrayList<>(survivors);
            if (n % 2 == 1) all.add(half + 1);
            Collections.sort(all);
            int newN = all.size();
            int nf = all.indexOf(f) + 1;
            int ns = all.indexOf(s) + 1;
            int[] sub = solve(newN, nf, ns);
            return new int[]{sub[0] + 1, sub[1] + 1};
        }
        int j = n + 1 - i;
        List<Integer> choices = new ArrayList<>();
        if (i == f || i == s) {
            choices.add(i);
        } else if (j == f || j == s) {
            choices.add(j);
        } else {
            choices.add(i);
            choices.add(j);
        }
        int minR = Integer.MAX_VALUE, maxR = Integer.MIN_VALUE;
        for (int c : choices) {
            List<Integer> next = new ArrayList<>(survivors);
            next.add(c);
            int[] r = enumerate(n, f, s, i + 1, next);
            minR = Math.min(minR, r[0]);
            maxR = Math.max(maxR, r[1]);
        }
        return new int[]{minR, maxR};
    }
}
